val ApiKeyPlugin = createApplicationPlugin("ApiKey") {
    onCall { call ->                                   // Plugins phase
        if (call.request.headers["X-Api-Key"] == null)
            call.respond(HttpStatusCode.Unauthorized)  // stop the chain
    }
}
